import { z } from "zod";

/**
 * Data model. Everything the operator edits (services, variables, prices,
 * charges) is plain data validated here, so the pricing engine never has to
 * know what "Amatitán" or "Turismo" mean.
 */

const slug = z.string().regex(/^[a-z0-9][a-z0-9_-]{0,39}$/, "Solo minúsculas, números, guion y guion bajo (máx. 40)");
const text = (max: number) => z.string().trim().min(1).max(max);
const money = z.number().finite().min(0).max(10_000_000);

/* ------------------------------------------------------------------ service */

export const variableSchema = z.object({
  key: slug,
  label: text(60),
  options: z.array(z.object({ value: slug, label: text(80) })).min(1).max(100),
  /** The variable only applies (and is only required) when these selections match. */
  showWhen: z.record(z.string(), z.string()).optional(),
});

/** One price: for a vehicle capacity, when every `sel` entry matches the order's selections. */
export const priceRowSchema = z.object({
  sel: z.record(z.string(), z.string()),
  capacity: z.number().int().min(1).max(200),
  price: money,
});

/**
 * Extra amount on top of the base price.
 * - manual: the operator enters a quantity (extra hours, extra moves).
 * - conditional: applied automatically when `when` matches the selections (schedule surcharges).
 * `amounts` is keyed by vehicle capacity ("14": 500) with "*" as fallback / flat amount.
 * perUnit: charged once per assigned vehicle instead of once per order.
 */
export const chargeSchema = z.object({
  id: slug,
  label: text(80),
  mode: z.enum(["manual", "conditional"]),
  perUnit: z.boolean(),
  amounts: z.record(z.string(), money),
  when: z.record(z.string(), z.string()).optional(),
});

export const serviceInputSchema = z.object({
  name: text(80),
  description: z.string().trim().max(500).optional(),
  active: z.boolean().default(true),
  variables: z.array(variableSchema).max(10),
  prices: z.array(priceRowSchema).max(2000),
  charges: z.array(chargeSchema).max(30),
});

export type Variable = z.infer<typeof variableSchema>;
export type PriceRow = z.infer<typeof priceRowSchema>;
export type Charge = z.infer<typeof chargeSchema>;
export type ServiceInput = z.infer<typeof serviceInputSchema>;
export type Service = ServiceInput & { id: string; createdAt: string; updatedAt: string };

/** Cross-field checks a schema cannot express. Returns human-readable problems. */
export function validateService(service: ServiceInput): string[] {
  const problems: string[] = [];
  const vars = new Map(service.variables.map((v) => [v.key, v]));
  if (vars.size !== service.variables.length) problems.push("Hay variables con la misma clave.");

  const options = (key: string) => new Set(vars.get(key)?.options.map((o) => o.value));
  for (const v of service.variables) {
    if (new Set(v.options.map((o) => o.value)).size !== v.options.length) problems.push(`"${v.label}" tiene opciones repetidas.`);
  }

  const checkRefs = (where: string, refs: Record<string, string> | undefined) => {
    for (const [k, val] of Object.entries(refs ?? {})) {
      if (!vars.has(k)) problems.push(`${where}: la variable "${k}" no existe.`);
      else if (!options(k).has(val)) problems.push(`${where}: "${val}" no es una opción de "${k}".`);
    }
  };
  for (const v of service.variables) checkRefs(`Variable "${v.label}"`, v.showWhen);
  for (const c of service.charges) checkRefs(`Cargo "${c.label}"`, c.when);

  if (new Set(service.charges.map((c) => c.id)).size !== service.charges.length) problems.push("Hay cargos con el mismo id.");
  for (const c of service.charges) {
    if (c.mode === "conditional" && !Object.keys(c.when ?? {}).length) problems.push(`El cargo "${c.label}" es condicional y necesita una condición.`);
  }

  const seen = new Set<string>();
  service.prices.forEach((row, i) => {
    checkRefs(`Precio #${i + 1}`, row.sel);
    const key = `${row.capacity}|${Object.keys(row.sel).sort().map((k) => `${k}=${row.sel[k]}`).join("&")}`;
    if (seen.has(key)) problems.push(`Precio #${i + 1} está duplicado.`);
    seen.add(key);
  });
  return problems;
}

