export const vehicleInputSchema = z.object({
  code: text(20),
  /** Top of the range of passengers this vehicle takes. */
  capacity: z.number().int().min(1).max(200),
  /** Bottom of the range; vehicles saved before ranges existed fall back to the standard sizes. */
  minCapacity: z.number().int().min(1).max(200).optional(),
  kind: z.enum(["car", "suv", "minivan", "van", "microbus", "midibus", "bus"]),
  model: z.string().trim().max(80).default(""),
  plates: z.string().trim().max(20).default(""),
  driver: z.string().trim().max(80).nullable().default(null),
  active: z.boolean().default(true),
});
export type VehicleInput = z.infer<typeof vehicleInputSchema>;
export type Vehicle = VehicleInput & { id: string; createdAt: string; updatedAt: string };

const STANDARD_SIZES = [6, 14, 20, 45];

/** The passengers a vehicle takes, as [from, to]. */
export function vehicleRange(v: Pick<VehicleInput, "capacity" | "minCapacity">): [number, number] {
  const i = STANDARD_SIZES.indexOf(v.capacity);
  return [v.minCapacity ?? (i > 0 ? STANDARD_SIZES[i - 1] + 1 : 1), v.capacity];
}

/**
 * Ranges are categories: several vehicles can share exactly the same range,
 * but two different ranges cannot overlap. Returns the clashing vehicle, if any.
 */
export function rangeConflict<T extends Pick<VehicleInput, "capacity" | "minCapacity">>(mine: Pick<VehicleInput, "capacity" | "minCapacity">, others: T[]): T | undefined {
  const [a, b] = vehicleRange(mine);
  return others.find((o) => {
    const [c, d] = vehicleRange(o);
    return !(a === c && b === d) && a <= d && c <= b;
  });
}

